#!/usr/bin/env node
// scaffold-modal-manager.js — v78 ship canonical modal helpers built on
// Shadcn Dialog so the LLM doesn't reinvent useState<boolean> + 5
// duplicate Dialog wrappers per page. Emits:
//   - app/hooks/useDisclosure.ts             open/close/toggle state
//   - app/hooks/useConfirm.ts                programmatic confirm() → Promise<boolean>
//   - app/components/modals/ConfirmModal.tsx Shadcn AlertDialog wrapper
//   - app/contexts/ConfirmProvider.tsx       hosts the confirm dialog at root
//
// Idempotent. Marker: '// Generated by scaffold-modal-manager'.
'use strict';

var fs = require('fs');
var path = require('path');

function parseArgs(argv) {
  var out = {};
  for (var i = 2; i < argv.length; i++) {
    var a = argv[i];
    if (a === '--target') out.target = argv[++i];
    else if (a === '--force') out.force = true;
    else if (a === '--dry-run') out.dryRun = true;
    else if (a === '--verbose' || a === '-v') out.verbose = true;
  }
  if (!out.target) { console.error('Usage: scaffold-modal-manager --target FRONTEND_DIR'); process.exit(1); }
  return out;
}

function marker() { return '// Generated by scaffold-modal-manager — DO NOT EDIT BY HAND. Re-run to refresh.'; }

function writeIfManaged(file, content, force, dryRun) {
  if (fs.existsSync(file)) {
    var existing = fs.readFileSync(file, 'utf-8');
    if (!/Generated by scaffold-modal-manager/.test(existing) && !force) {
      return { written: false, reason: 'exists-handauthored' };
    }
    if (existing === content) return { written: false, reason: 'unchanged' };
  }
  if (dryRun) return { written: false, reason: 'dry-run' };
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, content);
  return { written: true };
}

var USE_DISCLOSURE = [
  marker(),
  "import { useCallback, useState } from 'react';",
  '',
  'export function useDisclosure(initial = false) {',
  '  const [isOpen, setIsOpen] = useState(initial);',
  '  const open = useCallback(() => setIsOpen(true), []);',
  '  const close = useCallback(() => setIsOpen(false), []);',
  '  const toggle = useCallback(() => setIsOpen((v) => !v), []);',
  '  return { isOpen, open, close, toggle, setIsOpen };',
  '}',
  '',
].join('\n');

var USE_CONFIRM = [
  marker(),
  "import { createContext, useContext } from 'react';",
  '',
  'export interface ConfirmOptions {',
  '  title?: string;',
  '  description?: string;',
  '  confirmLabel?: string;',
  '  cancelLabel?: string;',
  "  variant?: 'default' | 'destructive';",
  '}',
  '',
  'export type ConfirmFn = (opts: ConfirmOptions) => Promise<boolean>;',
  '',
  'export const ConfirmContext = createContext<ConfirmFn | null>(null);',
  '',
  'export function useConfirm(): ConfirmFn {',
  '  const ctx = useContext(ConfirmContext);',
  "  if (!ctx) throw new Error('useConfirm must be used within <ConfirmProvider />');",
  '  return ctx;',
  '}',
  '',
].join('\n');

var CONFIRM_MODAL = [
  marker(),
  "import { Button } from '~/components/ui/button';",
  "import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '~/components/ui/dialog';",
  "import type { ConfirmOptions } from '~/hooks/useConfirm';",
  '',
  'export interface ConfirmModalProps extends ConfirmOptions {',
  '  open: boolean;',
  '  onConfirm: () => void;',
  '  onCancel: () => void;',
  '}',
  '',
  'export function ConfirmModal(props: ConfirmModalProps) {',
  "  const variant = props.variant === 'destructive' ? 'destructive' : 'default';",
  '  return (',
  '    <Dialog open={props.open} onOpenChange={(o) => { if (!o) props.onCancel(); }}>',
  '      <DialogContent data-testid="confirm-modal">',
  '        <DialogHeader>',
  "          <DialogTitle>{props.title ?? 'Confirm'}</DialogTitle>",
  '          {props.description && <DialogDescription>{props.description}</DialogDescription>}',
  '        </DialogHeader>',
  '        <DialogFooter>',
  '          <Button variant="outline" onClick={props.onCancel} data-testid="confirm-modal-cancel">',
  "            {props.cancelLabel ?? 'Cancel'}",
  '          </Button>',
  '          <Button variant={variant} onClick={props.onConfirm} data-testid="confirm-modal-confirm">',
  "            {props.confirmLabel ?? 'Confirm'}",
  '          </Button>',
  '        </DialogFooter>',
  '      </DialogContent>',
  '    </Dialog>',
  '  );',
  '}',
  '',
].join('\n');

var CONFIRM_PROVIDER = [
  marker(),
  "import { useCallback, useRef, useState, type ReactNode } from 'react';",
  "import { ConfirmContext, type ConfirmOptions } from '~/hooks/useConfirm';",
  "import { ConfirmModal } from '~/components/modals/ConfirmModal';",
  '',
  'export function ConfirmProvider({ children }: { children: ReactNode }) {',
  '  const [opts, setOpts] = useState<ConfirmOptions | null>(null);',
  '  const resolveRef = useRef<((v: boolean) => void) | null>(null);',
  '',
  '  const confirm = useCallback((o: ConfirmOptions) => {',
  '    setOpts(o);',
  '    return new Promise<boolean>((resolve) => { resolveRef.current = resolve; });',
  '  }, []);',
  '',
  '  const handle = (value: boolean) => () => {',
  '    setOpts(null);',
  '    resolveRef.current?.(value);',
  '    resolveRef.current = null;',
  '  };',
  '',
  '  return (',
  '    <ConfirmContext.Provider value={confirm}>',
  '      {children}',
  '      {opts && (',
  '        <ConfirmModal',
  '          open',
  '          {...opts}',
  '          onConfirm={handle(true)}',
  '          onCancel={handle(false)}',
  '        />',
  '      )}',
  '    </ConfirmContext.Provider>',
  '  );',
  '}',
  '',
].join('\n');

function main() {
  var args = parseArgs(process.argv);
  var files = [
    { p: 'app/hooks/useDisclosure.ts', c: USE_DISCLOSURE },
    { p: 'app/hooks/useConfirm.ts', c: USE_CONFIRM },
    { p: 'app/components/modals/ConfirmModal.tsx', c: CONFIRM_MODAL },
    { p: 'app/contexts/ConfirmProvider.tsx', c: CONFIRM_PROVIDER },
  ];
  var written = 0, skipped = 0;
  files.forEach(function (f) {
    var r = writeIfManaged(path.join(args.target, f.p), f.c, args.force, args.dryRun);
    if (r.written) written++; else skipped++;
    if (args.verbose) console.log('  ' + f.p + ': ' + (r.written ? 'wrote' : r.reason));
  });
  console.log('scaffold-modal-manager: ' + written + ' written, ' + skipped + ' skipped');
}

main();
